// Parse CSV URLhaus: skip baris komentar (#), ambil URL, filter malware_download.
const body = $input.first().json.body ?? $input.first().json.data ?? '';
const text = String(body);
const lines = text.split(/\r?\n/);
const MAX = 15;  // batch kecil per siklus (hormati rate-limit GSB)
const out = [];
for (const rawLine of lines) {
  const line = rawLine.replace(/\r$/, '').trim();
  if (!line || line.startsWith('#')) continue;
  // CSV: "id","dateadded","url","url_status","last_online","threat","tags","urlhaus_link","reporter"
  // Pecah manual per kolom bertanda kutip (robust thd koma dalam tanda kutip).
  const cols = [];
  const re = /"((?:[^"\\]|\\.)*)"/g;
  let m;
  while ((m = re.exec(line)) !== null) cols.push(m[1]);
  if (cols.length < 6) continue;
  const [id, dateadded, url, url_status, last_online, threat] = cols;
  if (threat !== 'malware_download') continue;   // fokus payload URL malware
  if (!/^https?:\/\//i.test(url)) continue;
  out.push({ json: { url, url_id: id, threat, tags: cols[6] || '', dateadded, urlhaus_link: cols[7] || '' } });
  if (out.length >= MAX) break;
}
return out;

// G1 v3: loop semua URL feed -> GSB -> auto-block via Wazuh AR (langsung di sini)
// -> hasil: 1 item ringkasan { blocked:[], review:[], total_checked }
const urls = $input.all();
const sd = $getWorkflowStaticData('global');
sd.proaktifCache = sd.proaktifCache || {};
const TTL = 24 * 60 * 60 * 1000;
const GSB_LABEL = {SOCIAL_ENGINEERING:'Phishing', MALWARE:'Malware', UNWANTED_SOFTWARE:'Unwanted software', POTENTIALLY_HARMFUL_APPLICATION:'Aplikasi berbahaya'};

const blocked = [];
const review = [];
let checked = 0;

// Ambil token Wazuh sekali (dipakai kalau ada yg auto-block)
async function getWazuhToken() {
  const r = await this.helpers.httpRequestWithAuthentication.call(this, 'httpBasicAuth', {
    method: 'POST',
    url: 'https://172.17.0.1:55000/security/user/authenticate',
    body: {},
    json: true,
    rejectUnauthorized: false,
  });
  return r && r.data ? r.data.token : '';
}

let wazuhToken = null;

for (const item of urls) {
  const alert = item.json;
  const url = alert.url;
  if (!url) continue;
  checked++;

  const cached = sd.proaktifCache[url];
  if (cached && (Date.now() - (cached.ts || 0)) < TTL) {
    continue; // sudah pernah dicek
  }

  // GSB lookup
  let gsb_threat = false, gsb_type = '', gsb_status = 'unavailable';
  try {
    const g = await this.helpers.httpRequestWithAuthentication.call(this, 'httpQueryAuth', {
      method: 'POST',
      url: 'https://safebrowsing.googleapis.com/v4/threatMatches:find',
      body: {
        client: { clientId: 'soar-ravi', clientVersion: '1.0' },
        threatInfo: {
          threatTypes: ['MALWARE','SOCIAL_ENGINEERING','UNWANTED_SOFTWARE','POTENTIALLY_HARMFUL_APPLICATION'],
          platformTypes: ['ANY_PLATFORM'], threatEntryTypes: ['URL'],
          threatEntries: [{ url }]
        }
      },
      json: true,
    });
    const matches = g && g.matches;
    if (Array.isArray(matches) && matches.length > 0) { gsb_threat = true; gsb_type = matches[0].threatType || 'THREAT'; gsb_status = 'threat'; }
    else { gsb_status = 'clean'; }
  } catch (e) { gsb_status = 'unavailable'; }

  sd.proaktifCache[url] = { stats: { gsb_status, gsb_threat, gsb_type }, ts: Date.now() };
  const label = gsb_threat ? ('TERDAFTAR - ' + (GSB_LABEL[gsb_type] || gsb_type)) : (gsb_status === 'clean' ? 'bersih' : 'tidak terverifikasi');

  if (gsb_threat) {
    // AUTO-BLOCK via Wazuh AR (agent 001)
    try {
      if (!wazuhToken) wazuhToken = await getWazuhToken.call(this);
      const ar = await this.helpers.httpRequest({
        method: 'PUT',
        url: 'https://172.17.0.1:55000/active-response?agents_list=001&wait_for_complete=true',
        headers: { 'Authorization': 'Bearer ' + wazuhToken, 'Content-Type': 'application/json' },
        body: JSON.stringify({ command: '!block-domain', arguments: [url] }),
        json: true, rejectUnauthorized: false, timeout: 30000,
      });
      blocked.push({ url, gsb: label, ar_ok: !!(ar && ar.error === 0) });
    } catch (e) {
      blocked.push({ url, gsb: label, ar_ok: false });
    }
  } else if (gsb_status === 'unavailable') {
    review.push({ url, gsb: label });
  }
  // clean -> silent
}

return [{ json: { blocked, review, total_checked: checked, timestamp: new Date().toISOString() } }];
